CREATE TABLE IF NOT EXISTS bank_reconciliation_sources ( id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, organization_id BIGINT UNSIGNED NOT NULL, bank_account_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(32) NOT NULL, effective_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, evidence_reference VARCHAR(255) NOT NULL, statement_reference VARCHAR(255) NOT NULL, verification_reference VARCHAR(255) NOT NULL, source_reference VARCHAR(100) NOT NULL, fund_event_id BIGINT UNSIGNED NULL, accounting_line_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_brs_source (bank_account_id, source_reference), KEY ix_brs_scope (organization_id, bank_account_id, effective_date, id), CONSTRAINT fk_brs_org FOREIGN KEY (organization_id) REFERENCES organizations(id), CONSTRAINT fk_brs_bank FOREIGN KEY (bank_account_id) REFERENCES bank_accounts(id), CONSTRAINT fk_brs_credit FOREIGN KEY (fund_event_id) REFERENCES fund_events(id), CONSTRAINT fk_brs_accounting FOREIGN KEY (accounting_line_id) REFERENCES voucher_accounting_lines(id), CONSTRAINT fk_brs_actor FOREIGN KEY (created_by) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
